158 | paf_read_header	(SF_PRIVATE *psf)
159 | {	PAF_FMT		paf_fmt ;
160 | 	int			marker ;
161 | 
162 | 	if (psf->filelength < PAF_HEADER_LENGTH)
163 | 		return SFE_PAF_SHORT_HEADER ;
164 | 
165 | 	memset (&paf_fmt, 0, sizeof (paf_fmt)) ;
166 | 	psf_binheader_readf (psf, "pm", 0, &marker) ;
167 | 
168 | 	psf_log_printf (psf, "Signature   : '%M'\n", marker) ;
169 | 
170 | 	if (marker == PAF_MARKER)
171 | 	{	psf_binheader_readf (psf, "E444444", &(paf_fmt.version), &(paf_fmt.endianness),
172 | 			&(paf_fmt.samplerate), &(paf_fmt.format), &(paf_fmt.channels), &(paf_fmt.source)) ;
173 | 		}
174 | 	else if (marker == FAP_MARKER)
175 | 	{	psf_binheader_readf (psf, "e444444", &(paf_fmt.version), &(paf_fmt.endianness),
176 | 			&(paf_fmt.samplerate), &(paf_fmt.format), &(paf_fmt.channels), &(paf_fmt.source)) ;
177 | 		}
178 | 	else
179 | 		return SFE_PAF_NO_MARKER ;
180 | 
181 | 	psf_log_printf (psf, "Version     : %d\n", paf_fmt.version) ;
182 | 
183 | 	if (paf_fmt.version != 0)
184 | 	{	psf_log_printf (psf, "*** Bad version number. should be zero.\n") ;
185 | 		return SFE_PAF_VERSION ;
186 | 		} ;
187 | 
188 | 	psf_log_printf (psf, "Sample Rate : %d\n", paf_fmt.samplerate) ;
189 | 	psf_log_printf (psf, "Channels    : %d\n", paf_fmt.channels) ;
190 | 
191 | 	psf_log_printf (psf, "Endianness  : %d => ", paf_fmt.endianness) ;
192 | 	if (paf_fmt.endianness)
193 | 	{	psf_log_printf (psf, "Little\n", paf_fmt.endianness) ;
194 | 		psf->endian = SF_ENDIAN_LITTLE ;
195 | 		}
196 | 	else
197 | 	{	psf_log_printf (psf, "Big\n", paf_fmt.endianness) ;
198 | 		psf->endian = SF_ENDIAN_BIG ;
199 | 		} ;
200 | 
201 | #ifdef MAGMA_ENABLE_FIXES
202 | 	if (paf_fmt.channels < 1 || paf_fmt.channels > SF_MAX_CHANNELS)
203 | 		return SFE_PAF_BAD_CHANNELS ;
204 | #endif
205 | #ifdef MAGMA_ENABLE_CANARIES
206 |     MAGMA_LOG("%MAGMA_BUG%", MAGMA_OR(paf_fmt.channels < 1, paf_fmt.channels > SF_MAX_CHANNELS));
207 | #endif
208 | 
209 | 	psf->datalength = psf->filelength - psf->dataoffset ;
210 | 
211 | 	psf_binheader_readf (psf, "p", (int) psf->dataoffset) ;
212 | 
213 | 	psf->sf.samplerate	= paf_fmt.samplerate ;
214 | 	psf->sf.channels 	= paf_fmt.channels ;
215 | 
216 | 	/* Only fill in type major. */
217 | 	psf->sf.format = SF_FORMAT_PAF ;
218 | 
219 | 	psf_log_printf (psf, "Format      : %d => ", paf_fmt.format) ;
220 | 
221 | 	/* PAF is by default big endian. */
222 | 	psf->sf.format |= paf_fmt.endianness ? SF_ENDIAN_LITTLE : SF_ENDIAN_BIG ;
223 | 
224 | 	switch (paf_fmt.format)
225 | 	{	case PAF_PCM_S8 :
226 | 					psf_log_printf (psf, "8 bit linear PCM\n") ;
227 | 					psf->bytewidth = 1 ;
228 | 
229 | 					psf->sf.format |= SF_FORMAT_PCM_S8 ;
230 | 
231 | 					psf->blockwidth = psf->bytewidth * psf->sf.channels ;
232 | 					psf->sf.frames = psf->datalength / psf->blockwidth ;
233 | 					break ;
234 | 
235 | 		case PAF_PCM_16 :
236 | 					psf_log_printf (psf, "16 bit linear PCM\n") ;
237 | 					psf->bytewidth = 2 ;
238 | 
239 | 					psf->sf.format |= SF_FORMAT_PCM_16 ;
240 | 
241 | 					psf->blockwidth = psf->bytewidth * psf->sf.channels ;
242 | 					psf->sf.frames = psf->datalength / psf->blockwidth ;
243 | 					break ;
244 | 
245 | 		case PAF_PCM_24 :
246 | 					psf_log_printf (psf, "24 bit linear PCM\n") ;
247 | 					psf->bytewidth = 3 ;
248 | 
249 | 					psf->sf.format |= SF_FORMAT_PCM_24 ;
250 | 
251 | 					psf->blockwidth = 0 ;
252 | 					psf->sf.frames = PAF24_SAMPLES_PER_BLOCK * psf->datalength /
253 | 											(PAF24_BLOCK_SIZE * psf->sf.channels) ;
254 | 					break ;
255 | 
256 | 		default :	psf_log_printf (psf, "Unknown\n") ;
257 | 					return SFE_PAF_UNKNOWN_FORMAT ;
258 | 					break ;
259 | 		} ;
